SELECT CASE WHEN YEAR(c.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(c.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END signup_cohort, COUNT(s.monthly_fee) monthly_fee_count, MAX(s.monthly_fee) - MIN(s.monthly_fee) monthly_fee_range FROM subscriptions s LEFT JOIN customers c ON s.customer_id = c.id GROUP BY CASE WHEN YEAR(c.signup_date) < 2024 THEN 'before_2024' WHEN YEAR(c.signup_date) = 2024 THEN '2024' ELSE 'after_2024' END HAVING monthly_fee_count >= 2 ORDER BY monthly_fee_range DESC;
